"use strict";const BOSS_CONFIG={pointsToAppear:1e3,pointsReward:350,speed:100,bulletSpeed:225,fireInterval:600,width:80,height:60};class Boss{constructor(){this.x=-BOSS_CONFIG.width,this.y=80,this.width=BOSS_CONFIG.width,this.height=BOSS_CONFIG.height,this.direction=1,this.hp=BOSS_CONFIG.pointsReward,this.lastFireTime=0,this.bullets=[],this.active=!0}update(s){this.x+=BOSS_CONFIG.speed*this.direction*s,this.x>window.innerWidth+this.width?(this.direction=-1,this.x=window.innerWidth+this.width):this.x<-this.width*2&&(this.direction=1,this.x=-this.width*2);for(let t=this.bullets.length-1;t>=0;t--)this.bullets[t].y+=BOSS_CONFIG.bulletSpeed*s,this.bullets[t].y>window.innerHeight+20&&this.bullets.splice(t,1);const i=Date.now();i-this.lastFireTime>BOSS_CONFIG.fireInterval&&(this.fire(),this.lastFireTime=i)}fire(){const s=window.game?.player;if(!s)return;const i=this.x+this.width/2,t=this.y+this.height;this.bullets.push({x:i,y:t,targetX:s.x,targetY:s.y,radius:6})}draw(s){s.save(),s.translate(this.x+this.width/2,this.y+this.height/2),s.fillStyle="#1a1a2e",s.strokeStyle="#ef4444",s.lineWidth=3,s.beginPath(),s.moveTo(-this.width/2,this.height/2),s.lineTo(-this.width/2,-this.height/3),s.lineTo(0,-this.height/2),s.lineTo(this.width/2,-this.height/3),s.lineTo(this.width/2,this.height/2),s.closePath(),s.fill(),s.stroke(),s.fillStyle="#ef4444",s.beginPath(),s.arc(-this.width/4,0,8,0,Math.PI*2),s.arc(this.width/4,0,8,0,Math.PI*2),s.fill(),s.restore(),s.fillStyle="#ef4444";for(const i of this.bullets)s.beginPath(),s.arc(i.x,i.y,i.radius,0,Math.PI*2),s.fill()}hit(s){return this.hp-=s,this.hp<=0?(this.active=!1,!0):!1}checkPlayerCollision(s){for(let i=this.bullets.length-1;i>=0;i--){const t=this.bullets[i],h=t.x-s.x,e=t.y-s.y;if(Math.sqrt(h*h+e*e)<s.radius+t.radius)return this.bullets.splice(i,1),!0}return s.x>this.x&&s.x<this.x+this.width&&s.y>this.y&&s.y<this.y+this.height}getCenter(){return{x:this.x+this.width/2,y:this.y+this.height/2}}}class BossManager{constructor(){this.boss=null,this.nextBossScore=BOSS_CONFIG.pointsToAppear,this.onSpawn=null}update(s){this.boss&&this.boss.active&&this.boss.update(s)}trySpawn(s){this.boss&&this.boss.active||s>=this.nextBossScore&&(this.spawn(),this.nextBossScore+=BOSS_CONFIG.pointsToAppear,this.onSpawn&&this.onSpawn())}spawn(){this.boss=new Boss}draw(s){this.boss&&this.boss.active&&this.boss.draw(s)}checkBulletCollision(s){if(!this.boss||!this.boss.active)return null;for(let i=s.length-1;i>=0;i--){const t=s[i];if(t.x>this.boss.x&&t.x<this.boss.x+this.boss.width&&t.y>this.boss.y&&t.y<this.boss.y+this.boss.height)return s.splice(i,1),{boss:this.boss,bullet:t}}return null}checkPlayerCollision(s){return this.boss&&this.boss.active?this.boss.checkPlayerCollision(s):!1}clear(){this.boss=null,this.nextBossScore=BOSS_CONFIG.pointsToAppear}}window.BOSS_CONFIG=BOSS_CONFIG,window.Boss=Boss,window.BossManager=BossManager;
